Computing the first derivative, we have

$$
\begin{aligned}
{f}^{′}(x) & = \left(3\left({(4\sqrt{x}+5{x}^{2}+x)}\right)\right)^{′}\\  & = \left(3\left({(4{x}^{1/2}+5{x}^{2}+x)}\right)\right)^{′}\\  & = 3\left(\frac{1}{2}\cdot 4{x}^{-1/2}+2\cdot 5x+1\right)\\  & = 3\left(2{x}^{-1/2}+10x+1\right)\,.\end{aligned}
$$

Computing the second derivative, we have

$$
\begin{aligned}
{f}^{″}(x) & = \left(3\left({(2{x}^{-1/2}+10x+1)}\right)\right)^{′}\\  & = 3\left(-\frac{1}{2}\cdot 2{x}^{-3/2}+10+0\right)\\  & = 3\left(-{x}^{-3/2}+10\right)\\  & = 3\left(-\frac{1}{\sqrt{{x}^{3}}}+10\right).\end{aligned}
$$

Computing the first derivative, we have

$$
\begin{aligned}
{f}^{′}(x) & = \left(3\left({(2{x}^{3}+4{x}^{2}-7)}\right)\right)^{′} &\\  & = 3\left(3\cdot 2{x}^{2}+2\cdot 4x-0\right)\\  & = 3\left(6{x}^{2}+8x\right)\,.\end{aligned}
$$

Computing the second derivative, we have

$$
\begin{aligned}
{f}^{″}(x) & = \left(3\left({(6{x}^{2}+8x)}\right)\right)^{′}\\  & = 3\left(2\cdot 6x+8\right)\\  & = 3\left(12x+8\right)\,.\end{aligned}
$$

Finally, evaluating the second derivative at $x=-2$, we obtain

$$
\begin{aligned}
{f}^{″}(-2) & = 3\left(12(-2)+8\right)\\  & = 3\left(-24+8\right)\\  & = 3\left(-16\right).\end{aligned}
$$

Computing the first derivative, we have

$$
\begin{aligned}
{f}^{′}(x) & = \left(3\left({({x}^{6}+{x}^{5})}\right)\right)^{′}\\  & = 3\left(6\cdot {x}^{5}+5\cdot {x}^{4}\right)\\  & = 3\left(6{x}^{5}+5{x}^{4}\right)\,.\end{aligned}
$$

Computing the second derivative, we have

$$
\begin{aligned}
{f}^{″}(x) & = \left(3\left({(6{x}^{5}+5{x}^{4})}\right)\right)^{′}\\  & = 3\left(5\cdot 6{x}^{4}+4\cdot 5{x}^{3}\right)\\  & = 3\left(30{x}^{4}+20{x}^{3}\right).\end{aligned}
$$

Computing the first derivative, we have

$$
\begin{aligned}
{g}^{′}(x) & = \left(3\left({(4{x}^{2}\sqrt{x}-2x+7)}\right)\right)^{′}\\  & = \left(3\left({(4{x}^{5/2}-2x+7)}\right)\right)^{′}\\  & = 3\left(4(\frac{5}{2}){x}^{3/2}-2+0\right)\\  & = 3\left(10{x}^{3/2}-2\right).\end{aligned}
$$

Computing the second derivative, we have

$$
\begin{aligned}
{g}^{″}(x) & = \left(3\left({(10{x}^{3/2}-2)}\right)\right)^{′}\\  & = 3\left(10(\frac{3}{2}){x}^{1/2}-0\right)\\  & = 3\left(15{x}^{1/2}\right)\\  & = 3\left(15\sqrt{x}\right).\end{aligned}
$$

Finally, evaluating the second derivative at $x=4$, we obtain

$$
\begin{aligned}
{g}^{″}(4) & = 3\left(15\sqrt{4}\right)\\  & = 3\left(15(2)\right)\\  & = 3\left(30\right).\end{aligned}
$$

Computing the first derivative, we have

$$
\begin{aligned}
{g}^{′}(x) & = \left(3\left({(-{x}^{3}+4x\sqrt{x})}\right)\right)^{′}\\  & = \left(3\left({(-{x}^{3}+4{x}^{3/2})}\right)\right)^{′}\\  & = 3\left(3(-{x}^{2})+\frac{3}{2}(4{x}^{1/2})\right)\\  & = 3\left(-3{x}^{2}+6{x}^{1/2}\right).\end{aligned}
$$

Computing the second derivative, we have

$$
\begin{aligned}
{g}^{″}(x) & = \left(3\left({(-3{x}^{2}+6{x}^{1/2})}\right)\right)^{′}\\  & = 3\left(2(-3x)+\frac{1}{2}(6{x}^{-1/2})\right)\\  & = 3\left(-6x+3{x}^{-1/2}\right)\\  & = 3\left(-6x+\frac{3}{\sqrt{x}}\right).\end{aligned}
$$

Finally, evaluating the second derivative at $x=1$, we obtain

$$
\begin{aligned}
{g}^{″}(1) & = 3\left(-6(1)+\frac{3}{\sqrt{1}}\right)\\  & = 3\left(-6+3\right)\\  & = 3\left(-3\right).\end{aligned}
$$
